#!/usr/bin/env python3
"""Build bounded, source-linked engine buying articles. Python standard library only."""
import json, re, html, hashlib
from pathlib import Path
from urllib.parse import quote
ROOT=Path(__file__).resolve().parents[1]
REPORT=ROOT/'docs/reports/engine-guides-20260910'
DATA=json.loads((REPORT/'engine-verification.json').read_text())
DEST=ROOT/'guides/engines';DEST.mkdir(parents=True,exist_ok=True)
H=lambda x:html.escape(str(x),quote=True)
def engine_slug(code): return code.lower().replace('.', '-')
def article_fact(e):
 return (str(len(e['applications']))+' documented applications') if e['displacement']=='Confirm exact donor displacement' else e['displacement']
COUNT=len(DATA['engines'])
BASE='https://asia-power.com'
CSS='''*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:30px}body{margin:0;color:#172033;background:#faf9f6;font:16px/1.75 system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}a{color:#15538d;text-underline-offset:4px}a:hover{color:#805300}a:focus-visible,summary:focus-visible{outline:3px solid #b77d17;outline-offset:5px}.skip{position:absolute;left:-9999px}.skip:focus{left:20px;top:12px;background:#fff;padding:10px;z-index:9}header{background:white;border-bottom:1px solid #e3e0d9}.nav{max-width:1160px;margin:auto;padding:22px 28px;display:flex;align-items:center;justify-content:space-between;gap:24px;flex-wrap:wrap}.brand{font-size:24px;font-weight:850;letter-spacing:-1px;color:#172033;text-decoration:none}.brand span{color:#a26a12}.navlinks{display:flex;gap:24px;flex-wrap:wrap;font-size:14px}.navlinks a{text-decoration:none;color:#374454}.wrap{max-width:1100px;margin:auto;padding:38px 28px 80px}.crumb{font-size:13px;color:#62707c;margin:0 0 28px}.eyebrow{font-size:12px;font-weight:750;letter-spacing:.15em;color:#80601e;text-transform:uppercase;margin:0 0 14px}h1{font-size:clamp(36px,5.5vw,66px);line-height:1.08;letter-spacing:-.045em;margin:0 0 22px;overflow-wrap:anywhere}h1 span{display:block;font-weight:450;color:#58616c;font-size:.58em;letter-spacing:-.03em;margin-top:12px}.lead{font-size:19px;line-height:1.65;max-width:800px;color:#4a5663}.facts{display:flex;gap:30px;flex-wrap:wrap;padding:22px 0;border-top:1px solid #dad8d0;border-bottom:1px solid #dad8d0;margin:28px 0}.facts b{display:block;font-size:20px;line-height:1.3}.facts small{color:#616c76;font-size:12px}.layout{display:grid;grid-template-columns:minmax(0,1fr) 235px;gap:44px;align-items:start}.article{min-width:0;background:#fff;padding:30px;border:1px solid #e5e2da;border-radius:9px}.article h2{font-size:24px;line-height:1.3;letter-spacing:-.025em;margin:35px 0 14px}.article h2:first-child{margin-top:0}.article h3{font-size:18px;margin:26px 0 8px}.article p{margin:0 0 16px}.article li{margin:8px 0}.article ul,.article ol{padding-left:22px}.note{border-left:3px solid #b78222;padding:12px 16px;background:#faf5e9;font-size:14px}.table-wrap{overflow:auto;max-width:100%;border:1px solid #dedfdc;border-radius:4px;margin:20px 0}table{width:100%;border-collapse:collapse;min-width:650px;font-size:14px;line-height:1.5}th{text-align:left;background:#f1f2ee;color:#45515c;font-size:13px;letter-spacing:.02em;text-transform:uppercase}th,td{padding:13px 12px;vertical-align:top;border-bottom:1px solid #e2e4df}td:first-child{font-weight:650}tr:last-child td{border-bottom:0}td a{overflow-wrap:anywhere}.toc{font-size:14px}.toc h2{font-size:15px;margin:0 0 14px}.toc a{display:block;padding:9px 0;text-decoration:none;border-bottom:1px solid #e0ded6}.cta{background:#172033;color:white;padding:24px;border-radius:6px;margin-top:26px;font-size:14px}.cta h2{color:white;margin:0 0 12px;font-size:20px}.cta p{color:#d9dee4}.button{display:inline-block;background:#e3b34f;color:#172033!important;border-radius:4px;padding:11px 17px;text-decoration:none;font-weight:750;line-height:1.5}.cta .secondary{display:block;margin-top:14px;color:#e7edf5}.source-list{font-size:13px}.source-list li{margin-bottom:12px}.muted{font-size:13px;color:#68737e}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.tile{display:block;background:white;border:1px solid #e2dfd6;padding:21px;text-decoration:none;color:#172033;border-radius:5px}.tile b{font-size:23px;display:block;letter-spacing:-.035em}.tile small{display:block;color:#697480;line-height:1.6;margin-top:5px}.brand-jump{display:flex;flex-wrap:wrap;gap:10px 18px;margin:22px 0;font-size:14px}.group{margin-top:38px}.group h2{font-size:24px}.related{margin-top:25px;padding-top:20px;border-top:1px solid #d7d8d1}.related a{margin-right:15px;display:inline-block}footer{border-top:1px solid #dedbd2;padding:26px 28px;font-size:13px;color:#64707b;max-width:1100px;margin:auto}details{border-top:1px solid #e3e3dd;padding:15px 0}summary{font-weight:650;cursor:pointer}details p{padding-top:10px}.index-intro{max-width:760px}.search{width:100%;max-width:580px;padding:14px 16px;border:1px solid #b7bcbf;border-radius:4px;font:inherit;margin:8px 0 22px}.empty{display:none}.hidden{display:none!important}@media(max-width:850px){.layout{grid-template-columns:1fr}.aside{order:-1}.toc{display:none}.aside>.cta{margin:0 0 5px}.cta{padding:20px}.grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:520px){.nav{padding:18px 20px;gap:14px}.navlinks{gap:16px;font-size:13px}.wrap{padding:26px 18px 48px}.article{padding:21px 17px}.grid{grid-template-columns:1fr}.facts{gap:20px}.lead{font-size:17px}.table-wrap{margin-left:0}.article h2{font-size:22px}}'''
def inline(t):
 t=H(t)
 t=re.sub(r'\[([^\]]+)\]\((https?://[^\s)]+)\)',r'<a href="\2">\1</a>',t)
 return re.sub(r'\*\*([^*]+)\*\*',r'<strong>\1</strong>',t)
def markdown(t):
 lines=t.splitlines();o=[];i=0
 while i<len(lines):
  s=lines[i].strip()
  if not s:i+=1;continue
  if s.startswith('# '):i+=1;continue
  if s.startswith('## '):o.append('<h2>'+inline(s[3:])+'</h2>');i+=1;continue
  if s.startswith('### '):o.append('<h3>'+inline(s[4:])+'</h3>');i+=1;continue
  if s.startswith('|'):
   rows=[]
   while i<len(lines) and lines[i].strip().startswith('|'):
    line=lines[i].strip();i+=1
    if re.fullmatch(r'[|:\-\s]+',line):continue
    rows.append([inline(v.strip()) for v in line.strip('|').split('|')])
   o.append('<div class="table-wrap" role="region" aria-label="Guide comparison table" tabindex="0"><table><thead><tr>'+''.join('<th>'+v+'</th>' for v in rows[0])+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+v+'</td>' for v in row)+'</tr>' for row in rows[1:])+'</tbody></table></div>');continue
  para=[]
  while i<len(lines) and lines[i].strip() and not lines[i].startswith(('#','|')):para.append(lines[i].strip());i+=1
  if para:o.append('<p>'+inline(' '.join(para))+'</p>')
 return '\n'.join(o)
def source_link(a, short=False):
 src=DATA['sources'][a['source']];url=src['url']+(f"#page={a['page']}" if a.get('page') else '')
 return f'<a href="{H(url)}" title="{H(src["title"])}">{H("Catalogue" if short else src["title"])}'+(f' · PDF p. {a["page"]}' if a.get('page') else '')+'</a>'
def table(e):
 return '<div class="table-wrap" role="region" aria-label="Documented vehicle applications; scroll horizontally for sources" tabindex="0"><table><thead><tr><th>Vehicle</th><th>Year / application dates</th><th>Variant</th><th>Market / scope</th><th>Evidence</th></tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+H(a[k])+'</td>' for k in ['vehicle','dates','variant','market'])+'<td>'+source_link(a, True)+'</td></tr>' for a in e['applications'])+'</tbody></table></div>'
def shell(title,description,url,content,schema,extra=''):
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{H(title)} | AsiaPower</title><meta name="description" content="{H(description)}"><link rel="canonical" href="{H(BASE+url)}"><meta property="og:title" content="{H(title)}"><meta property="og:description" content="{H(description)}"><meta property="og:url" content="{H(BASE+url)}"><meta property="og:type" content="article"><meta name="robots" content="index,follow"><style>{CSS}</style><script type="application/ld+json">{json.dumps(schema,ensure_ascii=False).replace('</','<\\/')}</script><script async src="https://www.googletagmanager.com/gtag/js?id=G-PB2J3VRX5J"></script><script>window.dataLayer=window.dataLayer||[];function gtag(){{dataLayer.push(arguments)}}gtag('js',new Date());gtag('config','G-PB2J3VRX5J');</script></head><body><a class="skip" href="#main">Skip to content</a><header><nav class="nav" aria-label="Main navigation"><a class="brand" href="/">Asia<span>Power</span></a><div class="navlinks"><a href="/engines/">Engine sourcing</a><a href="/guides/engines/">Engine guides</a><a href="/contact.html">Contact</a></div></nav></header><main class="wrap" id="main">{content}</main><footer>AsiaPower · Automotive engines and parts from China<br><a href="/guides/">Import guides</a> · <a href="/privacy.html">Privacy</a> · <a href="/contact.html">Contact AsiaPower</a></footer>{extra}</body></html>'''
def cta(e):
 msg=f"Hello AsiaPower, I am researching a {e['code']} replacement engine for my vehicle. Please help confirm compatibility and current availability. I can provide the vehicle details, engine-code photo and destination country."
 wa='https://wa.me/8616638801930?text='+quote(msg)
 return f'<section class="cta" id="inquiry"><h2>Check {H(e["code"])} sourcing</h2><p>Send your vehicle details and engine-code photo. Confirm the actual unit, included parts and delivery terms before payment.</p><a class="button" data-guide-enquiry="{H(e["code"])}" href="{H(wa)}" target="_blank" rel="noopener noreferrer">Ask on WhatsApp</a><a class="secondary" href="/contact.html">Use the enquiry page</a><p class="muted" style="color:#c7d0db;margin-bottom:0">Availability and price require confirmation.</p></section>'
def body(e):
 code=H(e['code']);apps=table(e)
 if e['code'] in ['BYD472QC','BYD472ZQB']:
  draft=(REPORT/'drafts'/f'{e["code"].lower()}-guide.md').read_text()
  return markdown(draft)
 sources='<ul class="source-list">'+''.join('<li>'+source_link(a)+'</li>' for a in { (a['source'],a.get('page')):a for a in e['applications']}.values())+''.join(f'<li><a href="{H(s["url"])}">{H(s["title"])}</a></li>' for s in e.get('extra_sources', []))+'</ul>'
 proof=''.join(f' <a href="{H(s["url"])}">{H(s["title"])}</a>.' for s in e.get('extra_sources', []))
 return f'''<h2 id="applications">Which vehicles use {code}?</h2><p>The table groups the applications documented for this engine code in one place. It is a sourced selection, not a claim to cover every trim, year or market. A listed vehicle is not an approval to interchange complete engines.</p>{apps}<p class="note">Dates are the cited catalogue’s application dates unless explicitly labelled model year. “End not stated” means the publication leaves the range open; it does not mean production continues today. Confirm the VIN, full engine marking and original-market parts data.</p><h2 id="identity">What matters for this code</h2><p>{H(e['buyer_focus'])}{proof}</p><p>Ask for a readable photograph of the engine marking and a wider photo locating it on the actual offered unit. Retain the donor vehicle identity and the seller’s stock reference with the quotation. The engine-cover appearance and a vehicle badge cannot replace this evidence.</p><h2 id="questions">Common {code} buying questions</h2><details open><summary>{H(e['question'])}</summary><p>{H(e['answer'])}{proof}</p></details><details><summary>What should a seller show before I buy this {code}?</summary><p>Ask for the actual unit’s identity, donor details, agreed included components and dated condition records. Request test methods and readings, not just “tested” or a claimed mileage. Keep the inspection evidence tied to the offered unit.</p></details><details><summary>Are knocking, smoke or a fault code proof of a common defect?</summary><p>These are symptoms to investigate, not a diagnosis or a measured failure rate for {code}. Have a qualified workshop establish the cause and scope of repair. This guide does not turn individual owner reports into a universal defect claim.</p></details><h2 id="inspection">How to read the inspection evidence</h2><p>Ask the workshop to record test conditions, engine temperature and cylinder identification. A cold-start video documents that start; it cannot establish long-term oil use. Relative compression compares cylinders and does not provide absolute cylinder pressure. <a href="https://www.picoauto.com/library/picoscope-automotive-training/training/compression-testing-by-pico-technology">Pico explains the limits and follow-up checks</a>.</p><p>Before ordering a replacement, preserve the receiving vehicle’s diagnosis. If the cause of the original failure remains unresolved, fitting another engine may not solve the problem. Service limits, fluids and commissioning procedures must come from the exact vehicle’s repair information, not a generic internet threshold.</p><h2 id="quote">Buying {code} from China for Africa</h2><p>{H(e.get("sourcing_note", "Availability must be confirmed for the specific offered unit."))}</p><p>Ask for a written component list: bare engine or long block, manifolds, fuel components, sensors, wiring, controllers and any transmission supplied. Include turbo or hybrid components only where applicable and explicitly agreed. The words “complete engine” are not a standard packing list.</p><p>Before shipment, agree the offered-unit identity, inspection evidence, preservation and packing, shipment terms, destination port and quotation validity. Compare the total agreed scope rather than engine price alone. AsiaPower confirms availability for the specific request; an application guide is not a live-stock guarantee.</p><p>Have the receiving workshop in the destination country confirm access to the relevant diagnostic information and needed service parts. Agree installation and commissioning scope, written warranty or inspection-period terms, exclusions, claim evidence, and who bears freight and labour costs. Manufacturer new-car coverage should not be assumed to apply to an independently exported used engine.</p><h2 id="sources">Sources and coverage</h2><p class="muted">Reviewed 10 September 2026. Catalogue references support the specified application rows. They do not certify a particular used unit, prove current supply, or measure failure frequency.</p>{sources}'''
outputs=[]
for e in DATA['engines']:
 slug=engine_slug(e['code']);url=f'/guides/engines/{slug}.html'
 desc=f"{e['code']} engine guide: documented {e['brand']} vehicle applications, year and market limits, identification, inspection and buying questions for African importers."
 title=f"{e['code']} engine: applications and buying guide"
 schema={'@context':'https://schema.org','@graph':[{'@type':'Article','headline':title,'description':desc,'datePublished':'2026-09-10','dateModified':'2026-09-10','author':{'@type':'Organization','name':'AsiaPower'},'publisher':{'@type':'Organization','name':'AsiaPower'},'mainEntityOfPage':BASE+url},{'@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'Engine guides','item':BASE+'/guides/engines/'},{'@type':'ListItem','position':2,'name':e['code'],'item':BASE+url}]}]}
 article=body(e)
 # Stable, meaningful navigation for full BYD drafts as well as generated articles.
 if e['code'].startswith('BYD472'):
  article=article.replace('<h2>Documented vehicle applications','<h2 id="applications">Documented vehicle applications').replace('<h2>Identify the vehicle','<h2 id="identity">Identify the vehicle').replace('<h2>Why the full code matters','<h2 id="identity">Why the full code matters').replace('<h2>Common buying questions','<h2 id="questions">Common buying questions').replace('<h2>Read the inspection','<h2 id="inspection">Read the inspection').replace('<h2>Installation, aftercare','<h2 id="quote">Installation, aftercare')
 links=['applications','identity','questions','inspection','quote'];labels=['Vehicle applications','Identification','Buying questions','Inspection evidence','Buying and delivery']
 toc='<nav class="toc" aria-label="On this page"><h2>In this guide</h2>'+''.join(f'<a href="#{a}">{b}</a>' for a,b in zip(links,labels))+'</nav>'
 models={a['vehicle'].split(' — ')[0] for a in e['applications']}
 related=sorted([x for x in DATA['engines'] if x['brand']==e['brand'] and x['code']!=e['code']],key=lambda x:-len(models & {a['vehicle'].split(' — ')[0] for a in x['applications']}))[:4]
 rel='<div class="related"><b>Related engine guides</b><br>'+''.join(f'<a href="{engine_slug(x["code"])}.html">{x["code"]}</a>' for x in related)+'<a href="/guides/engines/">All engine codes →</a></div>'
 content=f'<p class="crumb"><a href="/guides/">Guides</a> / <a data-finder-return href="/guides/engines/">Back to engine results</a> / {H(e["code"])}</p><p class="eyebrow">{H(" / ".join(e.get("application_brands", [e["brand"]])))} · Buyer reference</p><h1>{H(e["code"])}<span>Engine applications &amp; buying guide</span></h1><p class="lead">{H(e["buyer_focus"])}</p><div class="facts"><div><small>{"China application records" if e["displacement"]=="Confirm exact donor displacement" else "Documented displacement"}</small><b>{H(article_fact(e))}</b></div><div><small>Index</small><b>Full engine code</b></div><div><small>Reviewed</small><b>10 Sep 2026</b></div></div><div class="layout"><article class="article">{article}{rel}</article><aside class="aside">{toc}{cta(e)}</aside></div>'
 tracking=r'<script>try{const saved=sessionStorage.getItem("engineFinderReturn");if(saved&&/^\/guides\/engines\/\?/.test(saved)){document.querySelectorAll("[data-finder-return]").forEach(a=>a.href=saved)}}catch{}document.querySelectorAll("[data-guide-enquiry]").forEach(a=>a.addEventListener("click",()=>{if(typeof gtag==="function")gtag("event","engine_guide_whatsapp_click",{engine_code:a.dataset.guideEnquiry,link_url:"https://wa.me/8616638801930"})}));</script>'
 f=DEST/(slug+'.html');f.write_text(shell(title,desc,url,content,schema,tracking));outputs.append(str(f.relative_to(ROOT)))
# Index with crawlable links, optional local filtering; no API dependency.
from engine_directory import build_directory
content,indexjs=build_directory(DATA)
f=DEST/'index.html';f.write_text(shell('Petrol engine code guides for African buyers','Compare documented petrol engine applications and buying checks by full code. Chinese, Japanese, Korean, American and European engine applications for African importers.','/guides/engines/',content,{'@context':'https://schema.org','@type':'CollectionPage','name':'Petrol engine code guides','url':BASE+'/guides/engines/'},indexjs));outputs.append(str(f.relative_to(ROOT)))
# A separate sitemap avoids replacing the site's dynamic inventory sitemap.
urls=[BASE+'/guides/engines/']+[BASE+'/'+p for p in outputs if p.startswith('guides/engines/') and not p.endswith('index.html')]
sitemap='<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'+''.join('<url><loc>'+H(u)+'</loc><lastmod>2026-09-10</lastmod></url>\n' for u in urls)+'</urlset>\n'
(ROOT/'engine-guides-sitemap.xml').write_text(sitemap);outputs.append('engine-guides-sitemap.xml')
p=ROOT/'robots.txt';text=p.read_text();line='Sitemap: '+BASE+'/engine-guides-sitemap.xml'
if line not in text:p.write_text(text.rstrip()+'\n'+line+'\n')
outputs.append('robots.txt')
before={}
manifest=[dict(path=f,before_sha256=before.get(f),sha256=hashlib.sha256((ROOT/f).read_bytes()).hexdigest()) for f in outputs]
(REPORT/'release-manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
print(f'Built {len(DATA["engines"])} articles, index, discovery links and sitemap; {len(manifest)} scoped release files')
